    [('מזומן', 30000), ('לקוחות', 5000), ('מלאי מוצרים', 7000)], ('כיסאות, מראות וציוד', 85000), [('ספקים', 6000), ('מס ערך מוסף לשלם', 3000)], ('הלוואה מהבנק', 60000), 40000, 18000,
