   traps={'B10': [('=B3*B4', 'רשמתם את כל המינוי השנתי בינואר. השירות ניתן לאורך 12 חודשים: =B3*B4/12.')], 'B12': [('=B5', 'שכחתם את שכר הדירה של ינואר. הוא הוצאה של ינואר, גם אם ישולם בפברואר.')]},
